from __future__ import annotations

from typing import Any, Union

from pysnmp.proto import rfc1902

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.devices.snmp import SnmpPdu


class BKT(SnmpPdu):
    """Class provides attributes and private methods to manage a PDU of type BKT"""

    def __init__(
        self,
        host: str,
        timeout: Union[float, int] = 10,
        snmp_user: dict[str, Any] | None = None,
        community: str = "private",
    ) -> None:
        super().__init__(host, timeout, snmp_user, community)
        self._base_oid = ".1.3.6.1.4.1.47394.2.7"
        self._version = 1

    @property
    def _port_setting(self):
        return {
            DeviceStatus.ON: "Status:ON",
            DeviceStatus.OFF: "Status:OFF",
        }

    @property
    def _set_port_setting(self):
        return {
            DeviceStatus.ON: "ON",
            DeviceStatus.OFF: "OFF",
        }

    def _get_oid_value(self, value):
        return rfc1902.OctetString(self._set_port_setting[value])

    def _build_snmp_oid(self, port):
        return f"{self._base_oid}.{port}.0"
